import re
from decimal import Decimal, ROUND_HALF_UP

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_NUM = r"\d+(?:\.\d+)?"
_COMPONENT = rf"{_NUM}\s*[A-Za-z]+"
_COMPONENTS_RE = re.compile(rf"\s*{_COMPONENT}(?:\s*{_COMPONENT})*\s*")
_COMPONENT_FIND = re.compile(rf"({_NUM})\s*([A-Za-z]+)")

_ISO_RE = re.compile(
    r"P(?:(\d+(?:\.\d+)?)W)?(?:(\d+(?:\.\d+)?)D)?"
    r"(?:T(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?)?",
    re.IGNORECASE,
)

_CLOCK_FIELD = re.compile(r"\d+(?:\.\d+)?")


def _round(value: Decimal) -> int:
    return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # Bare non-negative integer: seconds.
    if re.fullmatch(r"\d+", s):
        return int(s)

    # ISO 8601 duration.
    if s[0] in "Pp":
        m = _ISO_RE.fullmatch(s)
        if not m or s[-1] in "Tt" or not any(m.groups()):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        weeks, days, hours, mins, secs = (Decimal(g) if g else Decimal(0) for g in m.groups())
        total = weeks * 604800 + days * 86400 + hours * 3600 + mins * 60 + secs
        return _round(total)

    # Clock notation: hh:mm:ss or mm:ss.
    if ":" in s:
        parts = [p.strip() for p in s.split(":")]
        if len(parts) not in (2, 3) or not all(_CLOCK_FIELD.fullmatch(p) for p in parts):
            raise ValueError(f"invalid clock duration: {text!r}")
        total = Decimal(0)
        for p in parts:
            total = total * 60 + Decimal(p)
        return _round(total)

    # Number+unit components, optionally separated by spaces.
    if not _COMPONENTS_RE.fullmatch(s):
        raise ValueError(f"invalid duration: {text!r}")
    total = Decimal(0)
    for num, unit in _COMPONENT_FIND.findall(s):
        key = unit.lower()
        if key not in _UNITS:
            raise ValueError(f"unknown unit: {unit!r}")
        total += Decimal(num) * _UNITS[key]
    return _round(total)

